import numpy as np
import time
from scipy.integrate import solve_ivp
from solver import Solver

def seirs_rhs_scipy(t, y, beta, sigma, gamma, omega):
    S, E, I, R = y
    SI = S * I
    dS = -beta * SI + omega * R
    dE = beta * SI - sigma * E
    dI = sigma * E - gamma * I
    dR = gamma * I - omega * R
    return [dS, dE, dI, dR]

def get_reference(problem):
    params = problem["params"]
    sol = solve_ivp(
        lambda t, y: seirs_rhs_scipy(t, y, params["beta"], params["sigma"], params["gamma"], params["omega"]),
        [problem["t0"], problem["t1"]],
        problem["y0"],
        method='DOP853',
        rtol=1e-10,
        atol=1e-12,
    )
    return sol.y[:, -1].tolist()

solver = Solver()

# Test cases
test_cases = [
    # Original example
    {
        "t0": 0.0, "t1": 400.0,
        "y0": [0.89, 0.01, 0.005, 0.095],
        "params": {"beta": 0.35, "sigma": 0.2, "gamma": 0.1, "omega": 0.002}
    },
    # Short time
    {
        "t0": 0.0, "t1": 10.0,
        "y0": [0.95, 0.02, 0.02, 0.01],
        "params": {"beta": 0.5, "sigma": 0.3, "gamma": 0.15, "omega": 0.005}
    },
    # Long time with oscillations
    {
        "t0": 0.0, "t1": 1000.0,
        "y0": [0.8, 0.05, 0.05, 0.1],
        "params": {"beta": 0.4, "sigma": 0.25, "gamma": 0.12, "omega": 0.003}
    },
    # High transmission
    {
        "t0": 0.0, "t1": 200.0,
        "y0": [0.99, 0.005, 0.003, 0.002],
        "params": {"beta": 1.0, "sigma": 0.5, "gamma": 0.2, "omega": 0.01}
    },
    # Low transmission, slow dynamics
    {
        "t0": 0.0, "t1": 500.0,
        "y0": [0.7, 0.1, 0.1, 0.1],
        "params": {"beta": 0.1, "sigma": 0.05, "gamma": 0.03, "omega": 0.001}
    },
    # Very long time
    {
        "t0": 0.0, "t1": 2000.0,
        "y0": [0.85, 0.05, 0.05, 0.05],
        "params": {"beta": 0.3, "sigma": 0.15, "gamma": 0.08, "omega": 0.001}
    },
]

all_pass = True
for i, problem in enumerate(test_cases):
    ref = get_reference(problem)
    ref_arr = np.array(ref)

    start = time.perf_counter()
    result = solver.solve(problem)
    elapsed = time.perf_counter() - start

    our_arr = np.array(result)

    # Check conservation
    cons_ok = np.isclose(np.sum(our_arr), 1.0, rtol=1e-5, atol=1e-8)

    # Check accuracy
    abs_diff = np.max(np.abs(our_arr - ref_arr))
    rel_diff = np.max(np.abs((our_arr - ref_arr) / (1e-8 + 1e-5 * np.abs(ref_arr))))
    acc_ok = np.allclose(our_arr, ref_arr, rtol=1e-5, atol=1e-8)

    status = "PASS" if (cons_ok and acc_ok) else "FAIL"
    if status == "FAIL":
        all_pass = False

    print(f"Test {i+1}: {status} | time={elapsed*1000:.2f}ms | abs_err={abs_diff:.3e} | rel_err={rel_diff:.3e} | sum={sum(result):.12f} | cons={cons_ok}")

print(f"\n{'All tests passed!' if all_pass else 'SOME TESTS FAILED!'}")
